create extension if not exists pgcrypto;
create table if not exists public.subscriptions(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,provider text not null check(provider='razorpay'),provider_subscription_id text not null unique,plan_code text not null,status text not null default 'created',provider_event text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create index if not exists subscriptions_user_created_idx on public.subscriptions(user_id,created_at desc);
create table if not exists public.usage_daily(user_id uuid not null references auth.users(id) on delete cascade,usage_date date not null default (timezone('utc',now()))::date,steps_used integer not null default 0 check(steps_used>=0),updated_at timestamptz not null default now(),primary key(user_id,usage_date));
alter table public.subscriptions enable row level security;alter table public.usage_daily enable row level security;revoke all on public.subscriptions from anon,authenticated;revoke all on public.usage_daily from anon,authenticated;grant all on public.subscriptions to service_role;grant all on public.usage_daily to service_role;
create or replace function public.yourvision_get_usage(p_user_id uuid) returns jsonb language plpgsql security definer set search_path=public as $$ declare v_used integer;v_limit integer;v_status text;begin if p_user_id is null then raise exception 'user id required';end if;select coalesce(steps_used,0) into v_used from public.usage_daily where user_id=p_user_id and usage_date=(timezone('utc',now()))::date;v_used:=coalesce(v_used,0);select status into v_status from public.subscriptions where user_id=p_user_id and status='active' order by updated_at desc limit 1;v_limit:=case when v_status='active' then null else greatest(0,coalesce(nullif(current_setting('app.free_daily_step_limit',true),'')::integer,50)) end;return jsonb_build_object('date',(timezone('utc',now()))::date,'steps_used',v_used,'daily_limit',v_limit,'plan',case when v_status='active' then 'premium' else 'free' end);end;$$;
revoke all on function public.yourvision_get_usage(uuid) from public,anon,authenticated;grant execute on function public.yourvision_get_usage(uuid) to service_role;
-- Usage increments must only be performed by a trusted server-side trace gateway. This site does not expose the extension localhost /visualize endpoint.